function tr1(s, k) {
  const v = D[s]; if (v) return v[k];
  for (const [re, ru, kk] of R) { const m = s.match(re); if (m) { const t = k ? kk : ru; return typeof t === 'function' ? t(...m) : s.replace(re, t); } }
  return null;
}
/** Translate one string: whole first, then sentence by sentence; anything unknown stays English. */
export function tx(s) {
  if (lang === 'en' || !s) return s;
  const k = lang === 'ru' ? 0 : lang === 'kk' ? 1 : -1;
  if (k < 0) return s;
  const lead = s.match(/^\s*/)[0], trail = s.match(/\s*$/)[0], core = s.trim().replace(/\s+/g, ' ');
  if (!core) return s;
  let out = tr1(core, k);
  if (out == null) {
    const parts = core.split(/(?<=[.!?…])\s+(?=[A-Z0-9“"(])/);
    if (parts.length > 1) {
      let any = false;
      out = parts.map(p => { let t = tr1(p, k); if (t == null && p.endsWith('.')) { const u = tr1(p.slice(0, -1), k); if (u != null) t = `${u}.`; } if (t != null) any = true; return t ?? p; }).join(' ');
      if (!any) out = null;
    } else if (core.endsWith('.')) { const u = tr1(core.slice(0, -1), k); if (u != null) out = `${u}.`; }
  }
  return out == null ? s : lead + out + trail;
}

